-- German B1-C2 continuation: four independent CEFR curricula, each with 28 original exercises.
-- Existing German A1-A2 content and learner records are unchanged.

ON CONFLICT (id) DO UPDATE SET
 skill=EXCLUDED.skill,level=EXCLUDED.level,objective=EXCLUDED.objective,instructions=EXCLUDED.instructions,
 content=EXCLUDED.content,answer_key=EXCLUDED.answer_key,explanation=EXCLUDED.explanation,
 estimated_time=EXCLUDED.estimated_time,tags=EXCLUDED.tags,prerequisites=EXCLUDED.prerequisites,
 srs=EXCLUDED.srs,success_criteria=EXCLUDED.success_criteria,objective_i18n=EXCLUDED.objective_i18n,
 language_code='de',status='published',version=EXCLUDED.version,updated_at=NOW();

ON CONFLICT (id) DO UPDATE SET
 title=EXCLUDED.title,level_min=EXCLUDED.level_min,level_max=EXCLUDED.level_max,
 weekly_themes=EXCLUDED.weekly_themes,status='published',language_code='de',
 version=EXCLUDED.version,updated_at=NOW();

UPDATE study_languages SET course_status='available',speech_supported=TRUE,content_version=2,updated_at=NOW()
WHERE language_code='de';
